const rad=THREE.MathUtils.degToRad;
function point(lat,lon,r=1){return new THREE.Vector3(r*Math.cos(rad(lat))*Math.cos(rad(lon)),r*Math.sin(rad(lat)),-r*Math.cos(rad(lat))*Math.sin(rad(lon)))}
